using System;using System.Reflection;using System.Threading;using System.Threading.Tasks;
namespace PZ3D {static class ConcurrentSnapshotTests {
 public static void Run(){var method=typeof(ModernDispatchQueue).GetMethod("ExecuteSnapshot");if(method==null)throw new Exception("FAIL: snapshot reads have separate non-cancelling queue path");var q=new ModernDispatchQueue();using(var started=new ManualResetEventSlim())using(var release=new ManualResetEventSlim()){var active=q.Execute(()=>{started.Set();release.Wait(5000);return null;});if(!started.Wait(5000))throw new Exception("fixture failed to start");int writes=0;var write=q.ExecuteMutation(()=>{writes++;return null;});var read=(Task<object>)method.Invoke(q,new object[]{new Func<object>(()=>"progress snapshot")});if(!read.Wait(2000)||Convert.ToString(read.Result)!="progress snapshot")throw new Exception("FAIL: snapshot cannot wait behind an active mutation");release.Set();active.Wait();write.Wait();if(writes!=1)throw new Exception("FAIL: snapshot polling cancelled a queued install");}Console.WriteLine("PASS: snapshot polling is concurrent and cannot cancel queued mutations");}
 public static int Main(){try{Run();return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}}
